package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.empty;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.databind.ObjectMapper;

import io.restassured.http.ContentType;

/**
 * @target-controller ClientAPIController
 * @target-api GET /client/sync
 * Test Plan: .nimbus/artifacts/test-plan/ClientAPIService_sync.md
 *
 * 인터셉터: ClientLoginInterceptor (/client/**) — Authorization: Bearer <KMS(CMK-4) 암호화 토큰> 필수.
 *   토큰 payload(JSON): tokenType(ACCESS 고정), expiredAt(yyyyMMddHHmmss), memberSeq, clientSeq.
 *   DB 조회 없이 토큰 자체만으로 세션(memberSeq/clientSeq)을 설정한다.
 * 컨트롤러: X-Manufacturer, X-Model, X-OS-Version, X-App-Version, Authorization 헤더 모두 required=true.
 * 외부 연동: 없음 (WireMock 불필요, detect-external-calls 결과 all REAL).
 * 응답 필드: code/message/data (ClientResultMap).
 */
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final DateTimeFormatter TOKEN_FMT = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
    private static Connection dbConnection;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/client-sync-setup.sql", ClientSyncBlackBoxTest.class);
        // ECGI(969101)를 실제 KMS(CMK-1) 암호문으로 치환 — kmsUtil.simpleDataCryptoList가 복호화하기 위해 필요
        TestUtil.encryptEcgi(dbConnection, 9691012, "1234567890");
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
            dbConnection.close();
        }
    }

    private static String buildToken(long memberSeq, long clientSeq, String tokenType, LocalDateTime expiredAt) {
        try {
            Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("tokenType", tokenType);
            payload.put("memberSeq", memberSeq);
            payload.put("clientSeq", clientSeq);
            payload.put("expiredAt", expiredAt.format(TOKEN_FMT));
            String json = new ObjectMapper().writeValueAsString(payload);
            return "Bearer " + TestUtil.kmsEncryptToken(json);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private static String validToken(long memberSeq, long clientSeq) {
        return buildToken(memberSeq, clientSeq, "ACCESS", LocalDateTime.now().plusHours(24));
    }

    // ========== NTC ==========

    /** [NTC_sync_fullData] 연동앱/ECGI/솔루션이 모두 존재하는 고객사 — 전체 필드 값 검증 */
    @Test
    void NTC_sync_fullData() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", validToken(969111, 969101))
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("200"))
            .body("message", equalTo("OK"))
            .body("data.latestTermsVersion", equalTo(969199))
            .body("data.latestNoticeVersion", equalTo(9999999))
            .body("data.mainBackgroundImageUrl", equalTo("https://test.example.com/bg1.png"))
            .body("data.interlockingAppVersion", equalTo(5))
            .body("data.interlockingAppList.size()", equalTo(1))
            .body("data.interlockingAppList[0].appName", equalTo("TestSyncApp"))
            .body("data.interlockingAppList[0].packageName", equalTo("com.test.syncapp"))
            .body("data.allowedEcgiList.size()", equalTo(1))
            .body("data.allowedEcgiList[0]", equalTo("1234567890"))
            .body("data.solutionList.size()", equalTo(1))
            .body("data.solutionList[0].solutionId", equalTo(9691013))
            .body("data.solutionList[0].solutionName", equalTo("TestSolution"))
            .body("data.solutionList[0].enabled", equalTo(true));
    }

    /** [NTC_sync_emptyLists] 연동앱/ECGI/솔루션이 없는 고객사 — 빈 배열 검증 */
    @Test
    void NTC_sync_emptyLists() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", validToken(969112, 969102))
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("200"))
            .body("data.mainBackgroundImageUrl", equalTo("https://test.example.com/bg2.png"))
            .body("data.interlockingAppVersion", equalTo(7))
            .body("data.interlockingAppList", empty())
            .body("data.allowedEcgiList", empty())
            .body("data.solutionList", empty());
    }

    /** [NTC_sync_bannedSolution] MEMBER_BAN_SOLN_PKG에 등록된 가입자 — solutionList[].enabled=false */
    @Test
    void NTC_sync_bannedSolution() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", validToken(969131, 969103))
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("200"))
            .body("data.mainBackgroundImageUrl", equalTo("https://test.example.com/bg3.png"))
            .body("data.interlockingAppVersion", equalTo(9))
            .body("data.solutionList.size()", equalTo(1))
            .body("data.solutionList[0].solutionId", equalTo(9691013))
            .body("data.solutionList[0].enabled", equalTo(false));
    }

    // ========== ATC ==========

    /** [ATC_missingAuthorization] Authorization 헤더 누락 — ClientLoginInterceptor가 즉시 차단 → 816 */
    @Test
    void ATC_missingAuthorization() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("816"))
            .body("message", equalTo("MISSING_TOKEN_VALUE"));
    }

    /** [ATC_invalidAuthorizationFormat] "Bearer " 접두어 없음 → 812 */
    @Test
    void ATC_invalidAuthorizationFormat() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", "NotBearerToken")
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("812"))
            .body("message", equalTo("INVALID_TOKEN"));
    }

    /** [ATC_expiredToken] 토큰 만료 → 802 */
    @Test
    void ATC_expiredToken() {
        String expired = buildToken(969111, 969101, "ACCESS", LocalDateTime.now().minusHours(1));
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", expired)
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("802"))
            .body("message", equalTo("TOKEN_EXPIRED"));
    }

    /** [ATC_wrongTokenType] tokenType=REFRESH (ACCESS 아님) → 855 */
    @Test
    void ATC_wrongTokenType() {
        String refreshToken = buildToken(969111, 969101, "REFRESH", LocalDateTime.now().plusHours(24));
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Manufacturer", "Samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", refreshToken)
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("855"))
            .body("message", equalTo("INVALID_TOKEN_TYPE"));
    }

    /** [ATC_missingXManufacturer] X-Manufacturer 헤더 누락 — Spring MissingRequestHeaderException → 011 */
    @Test
    void ATC_missingXManufacturer() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "1.0.0")
            .header("Authorization", validToken(969111, 969101))
        .when().get("/client/sync")
        .then().statusCode(200)
            .body("code", equalTo("011"))
            .body("message", equalTo("MISSING_REQUIRED_VALUE: X-Manufacturer"));
    }
}

