	        boolean checkCorporation = history.checkCorporation();

	        for (HistoryType historyType : historyTypeList) {
	        	ParamMap param = new ParamMap();
	        	switch(historyType) {
		        	case LOGIN: // 로그인 
		        		logger.info("History Type - LOGIN");
		        		String id = req.getParameter("id");
		        		String accountSeq = model.get("accountSeq") != null ? 
		        				String.valueOf(model.get("accountSeq")) : String.valueOf(session.getAttribute("loginAccountSeq"));
		        		param.put("id", id);
	        			param.put("accountSeq", accountSeq);
	        			param.put("ip", req.getRemoteAddr());
	        			param.put("reqType", reqType);

		        		historyDAO.insertPersonalInfoHistory(param);
		        		break;

		        	case PERSONAL_INFO_ACCESS: // 개인정보 조회
		        		logger.info("History Type - PERSONAL_INFO_ACCESS");
		        		if(checkCorporation) { 
		        			Object corpYn =  ((Map<String, Object>)  model.get("member")).get("corporationYn");
		        			boolean isCorporate = "1".equals(String.valueOf(corpYn));
		        			if (isCorporate) {
		        				logger.info("isCorporate: {}", isCorporate);
		        				break; // 기업 회원이라면 break;
		        			}
		        		}
		        		String dbQuery = MybatisExecuteInterceptor.getAccessExecutedSqls();
		        		if (CommonUtil.isNull(dbQuery)) {
		        			logger.info("query is null");
		        			break;
		        		}
		        		param.put("id", session.getAttribute("loginId"));
		        		param.put("accountSeq", session.getAttribute("loginAccountSeq"));
		        		param.put("ip", req.getRemoteAddr());
		        		param.put("reqType", reqType);
		        		param.put("dbQuery", dbQuery);

		        		historyDAO.insertPersonalInfoHistory(param);
		        		break;

		        	case EXCEL_DOWNLOAD: // 엑셀 다운로드
		        		logger.info("History Type - EXCEL_DOWNLOAD");
		        		String excelType = req.getParameter("excelType");

		        		if (!CommonUtil.isNull(excelType) && excelType.equals("all")) break; // 전체조회라면 break

		        		param.put("id", session.getAttribute("loginId"));
		        		param.put("accountSeq", session.getAttribute("loginAccountSeq"));
		        		param.put("ip", req.getRemoteAddr());
		        		param.put("reqType", reqType);
		        		param.put("reason", req.getParameter("excelReason"));

		        		historyDAO.insertExcelDownloadHistory(param);
		        		break;

		        	case PERMISSION: // 권한 관리
		        		logger.info("History Type - PERMISSION");
		        		ParamMap paramMap = null; // param 
		        		for (Object arg : args) {
		                    if (arg instanceof ParamMap) {
		                    	paramMap = (ParamMap) arg;
		                    	break;
		                    }
		                }
		        		String permissionReason = (String) paramMap.getString("reason");
		        		String accountType = (String) paramMap.getString("authz");
		        		String targetId = (String) paramMap.getString("id");

		        		if (!CommonUtil.isNull(permissionReason)) {
		        			param.put("id", session.getAttribute("loginId"));
		        			param.put("accountSeq", session.getAttribute("loginAccountSeq"));
		        			param.put("ip", req.getRemoteAddr());
		        			param.put("reqType", reqType);
		        			param.put("accountType", accountType);
		        			param.put("reason", permissionReason);
		        			param.put("targetAccountSeq",  model.get("accountSeq").toString());
		        			param.put("targetId", targetId);

		        			historyDAO.insertPermissionHistory(param);
		        			logger.info("insertPermissionHistory");
		        		} else {
		        			logger.info("permissionReason is Null");
		        		}
		        		break;

		        	case PERSONAL_INFO_DELETE: // 개인정보 파기
		        		logger.info("History Type - PERSONAL_INFO_DELETE");
		        		if (!model.get("err").toString().equals("000") || CommonUtil.isNull(model.get("deleteCount"))){
		        			logger.info("error: {}, deleteCount: {}", model.get("err").toString(), model.get("deleteCount"));
		        			logger.info("error or deleteCount is null");
		        			break;
		        		} 
		        		int deleteCount = (int) model.get("deleteCount");
		        		String deleteQuery = MybatisExecuteInterceptor.getDeleteExecutedSqls();

		        		if (CommonUtil.isNull(deleteQuery)) {
		        			logger.info("delete query is null");
		        			break;
		        		}

		        		if (deleteCount > 0) { 
		        			param.put("ip",  req.getRemoteAddr());
		        			param.put("id", session.getAttribute("loginId"));
		        			param.put("accountSeq", session.getAttribute("loginAccountSeq"));
		        			param.put("reqType", reqType);
		        			param.put("deleteCount", deleteCount);
		        			param.put("dbQuery", deleteQuery);

	        				historyDAO.insertPersonalInfoDelHistory(param);
		        		} else {
		        			logger.info("deleteCount <= 0");
		        		}
		        		break;

		        	case UNMASK: // 마스킹 해제 
		        		logger.info("History Type - UNMASK");
		        		boolean unmaskingYn =  Boolean.parseBoolean(req.getParameter("unmaskingYn"));
		        		String unmaskingReason = URLDecoder.decode(req.getParameter("reason"), "UTF-8");
		        		if (unmaskingYn && !CommonUtil.isNull(unmaskingReason)) {
		        			param.put("id", session.getAttribute("loginId"));
		        			param.put("accountSeq", session.getAttribute("loginAccountSeq"));
		        			param.put("ip", req.getRemoteAddr());
		        			param.put("reqType", reqType);
		        			param.put("reason", unmaskingReason);

		        			historyDAO.insertUnmaskHistory(param);
		        		} else {
		        			logger.info("unmaskingYn: {}, unmaskingReason is null? {}", unmaskingYn, CommonUtil.isNull(unmaskingReason));
		        		}
		        		break;

		        	case ACCOUNT_STATUS_CHANGE: // 계정 상태 변경
		        		logger.info("History Type - ACCOUNT_STATUS_CHANGE");
		        		ParamMap paramMap2 = null;
		        		for (Object arg : args) {
		        			if (arg instanceof ParamMap) {
		        				paramMap2 = (ParamMap) arg;
		        				break;
		        			}
		        		}
		        		String beforeStatus = paramMap2.getString("beforeStatus");
		        		String afterStatus = paramMap2.getString("afterStatus");
		        		if (!CommonUtil.isNull(beforeStatus) && !CommonUtil.isNull(afterStatus)) {
		        			long historySeq = historyDAO.getAccountHistorySeq();
		        			param.put("accountHistorySeq", historySeq);
		        			param.put("targetAccountSeq", paramMap2.get("targetAccountSeq"));
		        			param.put("targetAccountId", paramMap2.getString("targetAccountId"));
		        			param.put("beforeStatus", beforeStatus);
		        			param.put("afterStatus", afterStatus);
		        			param.put("managedAccountSeq", paramMap2.get("managedAccountSeq"));
		        			param.put("managedAccountId", paramMap2.getString("managedAccountId"));
		        			historyDAO.insertAccountHistory(param);
		        			logger.info("insertAccountHistory");
		        		} else {
		        			logger.info("status not changed");
		        		}
		        		break;
	        	}
	        }
        }
		logger.info("[ED][HistoryAspect]");
	}
}

