    /** [NTC_cancel_requestFromJoin] 가입(01) 상태 고객사 — 해지요청(02)으로 전이, err=000 */
    @Test
    void NTC_cancel_requestFromJoin() throws Exception {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/969201/cancel")
        .then().statusCode(200)
            .body("err", equalTo("000"));

        try (PreparedStatement ps = dbConnection.prepareStatement(
