            Assertions.assertEquals("02", rs.getString(1));
        }
    }

    /** [NTC_cancel_immediateWithMemberData] 해지(06) 상태 고객사 + 개인 가입자 1명 — 물리 삭제, err=000, deleteCount=1 */
    @Test
    void NTC_cancel_immediateWithMemberData() throws Exception {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/969202/cancel")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("deleteCount", equalTo(1));

        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT COUNT(*) FROM CLIENT WHERE CLIENT_SEQ = 969202")) {
            ResultSet rs = ps.executeQuery();
            Assertions.assertTrue(rs.next());
            Assertions.assertEquals(0, rs.getInt(1));
        }
        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT COUNT(*) FROM MEMBER WHERE MEMBER_SEQ = 9692021")) {
            ResultSet rs = ps.executeQuery();
            Assertions.assertTrue(rs.next());
            Assertions.assertEquals(0, rs.getInt(1));
        }
    }

    // ========== ATC ==========

    /** [ATC_cancel_alreadyProcessing] 해지요청(02) 상태 — 이미 처리중 → err=007 */
    @Test
    void ATC_cancel_alreadyProcessing() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/969203/cancel")
        .then().statusCode(200)
            .body("err", equalTo("007"))
            .body("errMsg", equalTo("Request service is already being processed."));
    }

    /** [ATC_cancel_lpsBlocked] LPS 가입(01) 상태 가입자 존재 — 해지 차단 → err=001 */
    @Test
    void ATC_cancel_lpsBlocked() throws Exception {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/969204/cancel")
        .then().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("UNABLE_TO_CLIENT_CANCEL_BECAUSE_EXIST_JOINED_MEMBER_IN_THE_LPS"));

        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT CANCEL_STATUS FROM CLIENT WHERE CLIENT_SEQ = 969204")) {
            ResultSet rs = ps.executeQuery();
            Assertions.assertTrue(rs.next());
            Assertions.assertEquals("06", rs.getString(1));
        }
    }

    /** [ATC_cancel_notFound] 존재하지 않는 clientSeq — getClient 빈 결과 → cancelStatus 불일치 → err=007 */
    @Test
    void ATC_cancel_notFound() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/9999999999/cancel")
        .then().statusCode(200)
            .body("err", equalTo("007"));
    }
}

