 * 응답 필드: err/errMsg/cryptoResult (ResultMap)
 */
class AdminCryptoPersonalBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-crypto-personal-teardown.sql", AdminCryptoPersonalBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-crypto-personal-setup.sql", AdminCryptoPersonalBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "cryptopersonal1", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/admin-crypto-personal-teardown.sql", AdminCryptoPersonalBlackBoxTest.class);
            dbConnection.close();
        }
    }

    // ========== NTC ==========

    /** [NTC_personal_decryptCtn] CTN 형태 평문을 KMS(CMK-2)로 암호화 후 복호화 요청 — 원문 일치 */
    @Test
    void NTC_personal_decryptCtn() {
        String ciphertext = TestUtil.kmsEncrypt("01099998888");

        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", ciphertext)
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("01099998888"));
    }

    /** [NTC_personal_decryptName] 이름 형태 평문(한글) 암호화 후 복호화 요청 — 원문 일치 */
    @Test
    void NTC_personal_decryptName() {
        String ciphertext = TestUtil.kmsEncrypt("홍길동");

        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", ciphertext)
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("홍길동"));
    }

    // ========== VTC ==========

    /** [VTC_cryptoContent_missing] cryptoContent 누락 — RuntimeLogicException → err=001 */
    @Test
    void VTC_cryptoContent_missing() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("MISSING_REQUIRED_VALUE : [cryptoContent]"));
    }

    /** [VTC_cryptoContent_invalidCiphertext] 유효하지 않은 암호문(평문 그대로) — 복호화 실패 → err=115 */
    @Test
    void VTC_cryptoContent_invalidCiphertext() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", "not-a-valid-ciphertext")
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("115"));
    }

    /** [VTC_cryptoContent_empty] cryptoContent 빈 문자열 — requiredValues 체크(isNull)에 걸려 err=001 */
    @Test
    void VTC_cryptoContent_empty() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", "")
        .when().post("/web/super/admin/crypto/personal")
        .then().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("MISSING_REQUIRED_VALUE : [cryptoContent]"));
    }
}

