package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.empty;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * @target-controller ECGIController
 * @target-api GET /web/admin/ecgis/ajax
 * Test Plan: .nimbus/artifacts/test-plan/ECGIService_getEcgiList.md
 *
 * 인터셉터: AdminLoginInterceptor (/web/admin/**) — 세션 로그인 필요. AUTHZ='02'(일반 관리자)는
 *   로그인 시 CLIENT_ACCOUNT를 통해 loginClientSeq가 세션에 설정되고, ecgiList는 이 clientSeq로 필터링한다.
 * 페이징: length(-1이면 무제한)/start, 응답: iTotalRecords/iTotalDisplayRecords/aaData, ECGI는 KMS(CMK-1) 복호화되어 반환.
 * 외부 연동: 없음 (WireMock 불필요).
 * 응답 필드: err/errMsg + iTotalRecords/aaData (ResultMap).
 */
class AdminEcgisAjaxBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId1;
    private static String sessionId2;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
