        TestUtil.executeSql(dbConnection, "sql/admin-history-sync-cancel-excel-make-teardown.sql", AdminHistorySyncCancelExcelMakeBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-history-sync-cancel-excel-make-setup.sql", AdminHistorySyncCancelExcelMakeBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "histexcelmk1", "testpw", dbConnection);
    }

    @AfterAll
