package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * @target-controller MemberController
 * @target-api GET /web/admin/members/qos/{memberSeq}
 * Test Plan: .nimbus/artifacts/test-plan/MemberService_getMemberQosStatus.md
 *
 * 인터셉터: AdminLoginInterceptor — 세션 로그인 필요. AUTHZ=CONSULTING(04)은 이 경로("/qos.*")만 허용되고,
 *   그 외 AUTHZ는 제한 없음. 본 테스트는 AUTHZ='02'(일반 관리자) 계정 사용.
 * MemberService.getMemberQosStatus는 clientSeq 필터 없이 memberSeq만으로 MEMBER_QOS_STATUS를 조회한다.
 * 외부 연동: 없음.
 * 응답 필드: err(default)/memberQosStatus (ResultMap).
 */
class AdminMemberQosStatusBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-members-qos-teardown.sql", AdminMemberQosStatusBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-members-qos-setup.sql", AdminMemberQosStatusBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "memberqos1", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/admin-members-qos-teardown.sql", AdminMemberQosStatusBlackBoxTest.class);
            dbConnection.close();
        }
    }

    // ========== NTC ==========

    /** [NTC_qos_controlled] QOS_STATUS='01'(제어중) 가입자 조회 */
    @Test
    void NTC_qos_controlled() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/members/qos/9696011")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("memberQosStatus.qosStatus", equalTo("01"));
    }

    /** [NTC_qos_released] QOS_STATUS='02'(해제) 가입자 조회 */
    @Test
    void NTC_qos_released() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/members/qos/9696012")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("memberQosStatus.qosStatus", equalTo("02"));
    }

    /** [NTC_qos_nullStatus] QOS_STATUS 컬럼이 NULL인 가입자 — row는 존재하되 상태값 없음 */
    @Test
    void NTC_qos_nullStatus() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/members/qos/9696013")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("memberQosStatus.qosStatus", nullValue());
    }

    // ========== ATC ==========

    /** [ATC_qos_noRow] MEMBER_QOS_STATUS row 자체가 없는 memberSeq — memberQosStatus 전체가 null */
    @Test
    void ATC_qos_noRow() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/members/qos/9696099")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("memberQosStatus", nullValue());
    }

    /** [ATC_qos_nonNumericMemberSeq] memberSeq가 숫자가 아님 — 경로 변수 타입 변환 실패 → err=999 */
    @Test
    void ATC_qos_nonNumericMemberSeq() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/members/qos/abc")
        .then().statusCode(200)
            .body("err", equalTo("999"));
    }

    /** [ATC_qos_noSession] 세션 없음 — URI에 "/ajax"가 없어 /web/login으로 리다이렉트(302) */
    @Test
    void ATC_qos_noSession() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/members/qos/9696011")
        .then().statusCode(302);
    }
}

