package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * @target-controller QuotaController
 * @target-api DELETE /web/admin/quota/groups (핸들러: deleteGroup)
 *
 * NOTE: 파이프라인 지시서의 경로 "/web/admin/quotagroups"는 QuotaController 소스와 불일치한다.
 * 실제 매핑은 클래스 레벨 "/web/admin/quota" + 메서드 레벨 "groups" → "/web/admin/quota/groups"이며,
 * 본 테스트는 소스코드 기준의 실제 경로를 사용한다 (Core Principle: 소스코드 우선).
 *
 * Test Plan: .nimbus/artifacts/test-plan/QuotaService_deleteGroups.md
 *
 * 인터셉터: AdminLoginInterceptor — 세션 로그인 필요.
 * 분기(QuotaService.deleteGroups):
 *   - deleteGroups로 삭제된 행이 0건(clientSeq 불일치/존재하지 않는 seq) → LogicException(GROUP_NOT_FOUND) → err=008
 *   - 정상 삭제 시 disbandMemberGroups로 소속 가입자의 MEMBER_GROUP_SEQ를 NULL로 해제, err=000, removeCnt
 * 외부 연동: 없음.
 * 응답 필드: err/errMsg/removeCnt (ResultMap).
 */
class AdminQuotaGroupsDeleteBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-quotagroups-delete-teardown.sql", AdminQuotaGroupsDeleteBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-quotagroups-delete-setup.sql", AdminQuotaGroupsDeleteBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "quotagroup1", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/admin-quotagroups-delete-teardown.sql", AdminQuotaGroupsDeleteBlackBoxTest.class);
            dbConnection.close();
        }
    }

    // ========== NTC ==========

    /** [NTC_deleteGroup_withMember] 가입자 1명이 소속된 그룹 삭제 — 그룹 삭제 + 가입자 MEMBER_GROUP_SEQ NULL 해제 */
    @Test
    void NTC_deleteGroup_withMember() throws Exception {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 969711)
        .when().delete("/web/admin/quota/groups")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("removeCnt", equalTo(1));

        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT MEMBER_GROUP_SEQ FROM MEMBER WHERE MEMBER_SEQ = 9697011")) {
            ResultSet rs = ps.executeQuery();
            Assertions.assertTrue(rs.next());
            Assertions.assertNull(rs.getObject(1));
        }
        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT COUNT(*) FROM MEMBER_GROUP WHERE MEMBER_GROUP_SEQ = 969711")) {
            ResultSet rs = ps.executeQuery();
            Assertions.assertTrue(rs.next());
            Assertions.assertEquals(0, rs.getInt(1));
        }
    }

    /** [NTC_deleteGroup_multiple] 가입자 없는 그룹 2건을 한 번에 삭제 — removeCnt=2 */
    @Test
    void NTC_deleteGroup_multiple() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 969712, 969713)
        .when().delete("/web/admin/quota/groups")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("removeCnt", equalTo(2));
    }

    /** [NTC_deleteGroup_emptyGroup] 가입자 없는 단일 그룹 삭제 — removeCnt=1 */
    @Test
    void NTC_deleteGroup_emptyGroup() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 969714)
        .when().delete("/web/admin/quota/groups")
        .then().statusCode(200)
            .body("err", equalTo("000"))
            .body("removeCnt", equalTo(1));
    }

    // ========== ATC ==========

    /** [ATC_deleteGroup_notFound] 존재하지 않는 memberGroupSeq — 삭제 0건 → err=008(GROUP_NOT_FOUND) */
    @Test
    void ATC_deleteGroup_notFound() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 9699999999L)
        .when().delete("/web/admin/quota/groups")
        .then().statusCode(200)
            .body("err", equalTo("008"))
            .body("errMsg", equalTo("GROUP_NOT_FOUND"));
    }

    /** [ATC_deleteGroup_noSession] 세션 없음 — /web/login 리다이렉트(302), follow 비활성화하여 검증 */
    @Test
    void ATC_deleteGroup_noSession() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .redirects().follow(false)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 969714)
        .when().delete("/web/admin/quota/groups")
        .then().statusCode(302);
    }
}

