import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import io.restassured.http.ContentType;

/**
 * @target-controller HistoryController (superadmin)
 * @target-api POST /web/super/admin/history/sync/cancel/excel/make
 * Test Plan: .nimbus/artifacts/test-plan/HistoryService_makeExcel.md
 *
 * 인터셉터: SuperAdminLoginInterceptor — 세션 로그인(AUTHZ=SYSTEM/07) 필요.
 * 분기(HistoryController.makeCanceledMemberExcel / HistoryService.makeExcel):
 *   - excelReason이 XSS 등 취약 패턴 → CommonUtil.isVulnerability → LogicException("VULNERABLE_VALUE","002") → err=002
 *   - searchType="CTN" → searchValue를 HMAC-SHA256 해시로 치환(빈 값이면 스킵), 그 외 값은 스킵 없이 진행
 *   - searchType!="CTN" → URLDecoder.decode(searchValue, UTF-8) 수행. searchValue가 없으면(null) NPE → err=999
 *   - 정상 흐름은 엑셀 생성을 백그라운드 스레드로 위임하고 즉시 err=000(default) 응답
 * 외부 연동: S3FileService(LocalStack, REAL, 백그라운드 스레드 내부에서만 사용) — WireMock 불필요.
 * 응답 필드: err/errMsg (ResultMap).
 */
class AdminHistorySyncCancelExcelMakeBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-history-sync-cancel-excel-make-teardown.sql", AdminHistorySyncCancelExcelMakeBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-history-sync-cancel-excel-make-setup.sql", AdminHistorySyncCancelExcelMakeBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "histexcelmk1", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/admin-history-sync-cancel-excel-make-teardown.sql", AdminHistorySyncCancelExcelMakeBlackBoxTest.class);
            dbConnection.close();
        }
    }

    // ========== NTC ==========

    /** [NTC_makeExcel_searchByCtn] searchType=CTN — 해시 치환 후 정상 접수, err=000 */
    @Test
    void NTC_makeExcel_searchByCtn() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "CTN")
            .formParam("searchValue", "01011112222")
            .formParam("searchStartDate", "2026-01-01")
            .formParam("searchEndDate", "2026-12-31")
            .formParam("excelReason", "해지 동기화 이력 엑셀 다운로드")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_searchByName] searchType=NAME — URL 디코딩 정상 처리, err=000 */
    @Test
    void NTC_makeExcel_searchByName() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "NAME")
            .formParam("searchValue", "TestUser")
            .formParam("searchStartDate", "2026-01-01")
            .formParam("searchEndDate", "2026-12-31")
            .formParam("excelReason", "업무 조회")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_ctnEmptyValue] searchType=CTN + searchValue 빈 문자열 — 해시 스킵 분기, err=000 */
    @Test
    void NTC_makeExcel_ctnEmptyValue() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchStartDate", "2026-01-01")
            .formParam("searchEndDate", "2026-12-31")
            .formParam("excelReason", "전체 조회")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ========== VTC ==========

    /** [VTC_excelReason_xss] excelReason에 XSS 문자열 — CommonUtil.isVulnerability 차단 → err=002 */
    @Test
    void VTC_excelReason_xss() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "NAME")
            .formParam("searchValue", "TestUser")
            .formParam("excelReason", "<script>alert('xss')</script>")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("002"))
            .body("errMsg", equalTo("VULNERABLE_VALUE"));
    }

    /** [NTC_makeExcel_searchValueMissing] searchValue 파라미터 자체가 없어도 ParamMap.getString은 ""을 반환
     *  (null 아님) — URLDecoder.decode("")도 정상 처리되어 err=000 */
    @Test
    void NTC_makeExcel_searchValueMissing() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "NAME")
            .formParam("excelReason", "정상 사유")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ========== ATC ==========

    /** [ATC_noSession] 세션 없음 — URI에 "/ajax"가 없어 SuperAdminLoginInterceptor가 /web/login으로 리다이렉트(302).
     *  RestAssured는 POST 302를 기본적으로 follow하지 않는다. */
    @Test
    void ATC_noSession() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchType", "NAME")
            .formParam("searchValue", "TestUser")
            .formParam("excelReason", "정상 사유")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().statusCode(302);
    }
}

