 * 분기(TrafficController.makeTrafficExcel):
 *   - excelReason이 XSS 등 취약 패턴 → CommonUtil.isVulnerability → LogicException("VULNERABLE_VALUE","002") → err=002
 *   - memberSeq 파라미터가 없으면(빈 문자열) TrafficService.getTrafficListForExcel을 동기 호출(엑셀 파일 생성 자체는 비동기 스레드)
 *   - 정상 흐름은 err=000(default) 즉시 응답
 * 외부 연동: S3FileService(LocalStack, REAL, 백그라운드 스레드 내부에서만 사용) — WireMock 불필요.
 * 응답 필드: err/errMsg (ResultMap).
 */
class AdminTrafficExcelMakeBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionIdSystem;
    private static String sessionIdNormal;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-trafficexcel-make-teardown.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-trafficexcel-make-setup.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        sessionIdSystem = TestUtil.adminLogin(BASE_URL, "trafficxlsys", "testpw", dbConnection);
        sessionIdNormal = TestUtil.adminLogin(BASE_URL, "trafficxlnrm", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/admin-trafficexcel-make-teardown.sql", AdminTrafficExcelMakeBlackBoxTest.class);
            dbConnection.close();
        }
    }

    // ========== NTC ==========

    /** [NTC_makeExcel_calculateMonthTotal] 정산(CALCULATE)/월별/전체 트래픽 엑셀 생성 요청 */
    @Test
    void NTC_makeExcel_calculateMonthTotal() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionIdSystem)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "업무용 정산 조회")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_realtimeDayUpload] 실시간(REAL_TIME)/일별/업로드 트래픽 엑셀 생성 요청 */
    @Test
    void NTC_makeExcel_realtimeDayUpload() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionIdSystem)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "REAL_TIME")
            .formParam("searchPeriodType", "SEARCH_FOR_DAY")
            .formParam("searchTrafficType", "UPLOAD")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260302")
            .formParam("excelReason", "업무용 실시간 조회")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_searchByCtn] CTN 검색어 지정(해시 치환 분기) — 다운로드 트래픽 */
    @Test
    void NTC_makeExcel_searchByCtn() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionIdSystem)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "DOWNLOAD")
            .formParam("searchType", "CTN")
            .formParam("searchValue", "01099998888")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "CTN 검색 조회")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ========== VTC ==========

    /** [VTC_excelReason_xss] excelReason에 XSS 문자열 — CommonUtil.isVulnerability 차단 → err=002 */
    @Test
    void VTC_excelReason_xss() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionIdSystem)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "<script>alert('xss')</script>")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(200)
            .body("err", equalTo("002"))
            .body("errMsg", equalTo("VULNERABLE_VALUE"));
    }

    // ========== ATC ==========

    /** [ATC_makeExcel_forbiddenNonSystem] AUTHZ='02'(일반 관리자) — 블랙리스트 경로 차단 → 403 */
    @Test
    void ATC_makeExcel_forbiddenNonSystem() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionIdNormal)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "업무용 테스트")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(403);
    }

    /** [ATC_makeExcel_noSession] 세션 없음 — /web/login 리다이렉트(302). POST는 RestAssured가 기본적으로 follow하지 않는다. */
    @Test
    void ATC_makeExcel_noSession() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "업무용 테스트")
        .when().post("/web/admin/traffic/excel/make")
        .then().statusCode(302);
    }
}

